from seg1 import *
def tbl(v,hdr,rows,cols):
    h=f'<div class="g m" style="grid-template-columns:{cols};padding:0 0 12px;gap:16px">'+''.join(f'<span>{x}</span>' for x in hdr)+'</div>'
    r=''.join(f'<div class="g" style="grid-template-columns:{cols};padding:18px 0;gap:16px;align-items:center;border-top:1px solid {"#0d0d0d" if v==3 else "var(--ln)"};font-size:16px">'+''.join(f'<span>{c}</span>' for c in row)+'</div>' for row in rows)
    return h+r+f'<div style="border-top:1px solid {"#0d0d0d" if v==3 else "var(--ln)"}"></div>'
def tag(t,k=''): return f'<span class="pill {k}">{t}</span>'
def box(v,inner,pad=32,extra=''): return f'<div class="card" style="padding:{pad}px;{extra}">{inner}</div>'
def head(v,t,s='',right=''): return f'<div class="row" style="justify-content:space-between;align-items:end;margin-bottom:32px"><div><div class="m">{s}</div><h2 class="t" style="margin-top:10px">{t}</h2></div>{right}</div>'
def auth(kind):
    T={'login':('Welcome back','Sign in to manage your tickets.',['Email','Password'],'Sign in','New here? Create an account'),'signup':('Create account','Tickets, orders and events in one place.',['Full name','Email','Password'],'Create account','Already registered? Sign in'),'reset':('Reset password','We will email you a secure link.',['Email'],'Send reset link','Back to sign in')}[kind]
    def f(v):
        form=f'<div class="logo">UNTITLED</div><div class="l" style="font-size:56px;margin:{"90px" if v!=3 else "70px"} 0 12px">{T[0]}</div><div class="sub">{T[1]}</div>'+''.join(f'<div class="m lab">{x}</div><div class="in">{"•••••••••" if x=="Password" else "Enter "+x.lower()}</div>' for x in T[2])+f'<div class="btn {"a" if v==3 else ""}" style="width:100%;margin-top:28px;height:54px">{T[3]}</div>'+('<div class="btn o" style="width:100%;margin-top:12px;height:54px">Continue with Google</div>' if kind!='reset' else '')+f'<div class="m" style="text-align:center;margin-top:24px">{T[4]}</div>'
        art=['w_ember','w_peach','w_mag'][v-1]; 
        if v==1: return f'<div class="g" style="grid-template-columns:1fr 1fr;gap:56px;height:760px"><div style="padding:24px 0 0 40px;max-width:520px">{form}</div><div class="art" style="border-radius:2px;background-image:url({A}{"a5" if kind=="login" else "tall_peach" if kind=="signup" else "tall_ember"}.jpg)"></div></div>'
        if v==2: return f'<div class="card" style="padding:14px;display:grid;grid-template-columns:1fr 1fr;gap:20px;height:760px;border-radius:36px"><div class="art" style="border-radius:26px;background-image:url({A}{"tall_mag" if kind!="signup" else "tall_peach"}.jpg);padding:32px;display:flex;align-items:flex-end;color:#fff"><div class="l" style="font-size:44px">Tickets for every kind of night.</div></div><div style="padding:36px 56px">{form}</div></div>'
        return f'<div class="g" style="grid-template-columns:1fr 560px;gap:0;height:760px;border:1.5px solid #0d0d0d;border-radius:28px;overflow:hidden"><div style="padding:56px 96px">{form}</div><div class="art" style="background-image:url({A}sph_{"mag" if kind!="signup" else "ember"}.jpg);border-left:1.5px solid #0d0d0d"></div></div>'
    return f
def filters(v):
    chips=[('All',1),('Concert',0),('Sport',0),('Theatre',0),('Conference',0),('Festival',0)]
    c=''.join(tag(n,'k' if on else '') for n,on in chips)
    if v==1: return '<div class="m">Discover</div><div class="l" style="font-size:88px;margin:16px 0 36px">Events near you</div><div class="row" style="gap:0;border:1px solid #0d0d0d"><div class="in" style="flex:2;border:0;border-right:1px solid #0d0d0d;border-radius:0">Search events, artists, venues</div><div class="in" style="flex:1;border:0;border-right:1px solid #0d0d0d;border-radius:0">Kamloops, BC</div><div class="in" style="flex:1;border:0;border-radius:0">Any date</div><span class="btn a" style="border-radius:0;height:56px">Search</span></div><div class="row" style="gap:10px;margin-top:20px">'+c+'</div>'
    if v==2: return f'<div style="text-align:center"><div class="l" style="font-size:72px;margin-bottom:28px">Discover events</div><div class="card row" style="width:900px;margin:0 auto;height:72px;border-radius:999px;align-items:center;padding:0 10px 0 28px;justify-content:space-between"><span style="color:#888">Search events, artists, venues</span><span class="btn a" style="height:52px">Search</span></div><div class="row" style="gap:10px;margin-top:24px;justify-content:center">{c}</div></div>'
    return '<div class="row" style="justify-content:space-between;align-items:end"><div class="l" style="font-size:150px">Discover</div><div class="m" style="margin-bottom:20px">1,284 events</div></div><div class="hr" style="margin:24px 0"></div><div class="row" style="gap:10px;justify-content:space-between"><div class="row" style="gap:10px">'+c+'</div><div class="row" style="gap:10px">'+tag('Kamloops')+tag('This month')+tag('Any price')+'</div></div>'
def results(v):
    if v==3: return events(3)
    if v==1:
        rows=''.join(f'<div class="g" style="grid-template-columns:90px 80px 1.2fr 1.6fr 140px 120px;gap:20px;align-items:center;padding:16px 0;border-top:1px solid #0d0d0d"><div style="font-size:30px;font-weight:300">{e[0][:2]}<span class="m" style="margin-left:6px">{e[0][3:]}</span></div><div class="art" style="width:64px;height:64px;background-image:url({A}{e[5]}.jpg)"></div><div style="font-size:22px;font-weight:500;letter-spacing:-.02em">{e[1]}</div><div class="sub" style="font-size:15px">{e[2]} at {e[3]}. Doors 19:00, all ages.</div><div class="m">{e[4]}</div>{tag(e[2])}</div>' for e in EV)
        return head(1,'June to August','Results',tag('Sort: date'))+rows+'<div style="border-top:1px solid #0d0d0d"></div>'
    return head(2,'12 events found','Results',tag('Sort: date'))+'<div class="g" style="grid-template-columns:repeat(3,1fr);gap:24px">'+''.join(evcard(2,e) for e in EV)+'</div>'
def calendar(v):
    ev={4,7,11,14,15,18,21,22,25,28}; 
    cells=''
    for d in range(1,31):
        k=d+1; hot=d in (14,15); has=d in ev
        if v==1: cells+=f'<div style="height:104px;border-top:1px solid #0d0d0d;border-right:1px solid var(--ln);padding:10px"><span style="font-size:15px">{d}</span>{"<div class=pill style=margin-top:10px;display:flex>Summer Stage</div>" if d==14 else ("<div class=pill style=margin-top:10px;display:flex>Cup Final</div>" if d==21 else ("<span class=dot style=display:block;margin-top:18px></span>" if has else ""))}</div>'
        elif v==2: cells+=f'<div style="height:96px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px"><span style="width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:17px;{"background:var(--acc);color:#fff" if hot else ""}">{d}</span>{"<span class=dot></span>" if has else "<span style=height:10px></span>"}</div>'
        else: cells+=f'<div style="height:92px;border-top:1.5px solid #0d0d0d;padding:10px 0"><span class="l" style="font-size:40px;{"color:var(--acc)" if hot else ""}">{d:02d}</span>{"<span class=dot style=margin-left:8px></span>" if has else ""}</div>'
    off='<div></div>'*6
    hd=''.join(f'<div class="m" style="text-align:{"center" if v==2 else "left"}">{x}</div>' for x in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])
    body=f'<div class="g" style="grid-template-columns:repeat(7,1fr);gap:{"0 8px" if v==3 else "0"}">{hd}{off}{cells}</div>'
    return head(v,'November','Calendar',tag('Month','k')+tag('List'))+(box(v,body,28) if v==2 else body)
# ---- event page ----
def evhero(v):
    if v==1: return nav(1)+f'<div class="art" style="height:560px;margin-top:32px;border-radius:2px;background-image:url({A}w_half.jpg);position:relative"><div class="art" style="position:absolute;left:48px;bottom:-56px;width:120px;height:120px;border-radius:50%;border:6px solid #fff;background-image:url({A}a0.jpg)"></div></div><div class="row" style="justify-content:space-between;align-items:end;margin-top:84px"><div><div class="m">Concert · Kamloops · Sat 14 Jun, 20:00</div><div class="l" style="font-size:104px;margin-top:12px">Summer Stage</div></div><div class="row" style="gap:12px"><span class="btn o">Save</span><span class="btn a" style="padding:0 44px">Buy tickets</span></div></div>'
    if v==2: return nav(2)+f'<div class="art" style="height:560px;margin-top:28px;border-radius:36px;background-image:url({A}w_peach.jpg);position:relative"></div><div style="text-align:center;margin-top:-64px;position:relative"><div class="art" style="width:128px;height:128px;border-radius:50%;margin:0 auto;border:6px solid #fff;background-image:url({A}a1.jpg)"></div><div class="l" style="font-size:84px;margin:20px 0 14px">Summer Stage</div><div class="row" style="gap:10px;justify-content:center">{tag("Sat 14 Jun")}{tag("20:00")}{tag("Kamloops")}{tag("All ages")}</div><div class="btn a" style="margin-top:28px;padding:0 60px">Buy tickets</div></div>'
    return nav(3)+f'<div class="g" style="grid-template-columns:1fr 1fr;gap:40px;align-items:end"><div><div class="m">Concert · All ages</div><div class="l" style="font-size:150px;margin:20px 0 32px">Summer<br>Stage</div><div class="row" style="gap:16px;align-items:center"><div class="art" style="width:72px;height:72px;border-radius:50%;background-image:url({A}a0.jpg)"></div><div><div style="font-size:18px">Sat 14 Jun · 20:00</div><div class="m">Riverside Arena, Kamloops</div></div></div><div class="btn a" style="margin-top:36px;padding:0 52px">Buy tickets</div></div><div class="art" style="height:600px;border-radius:28px;border:1.5px solid #0d0d0d;background-image:url({A}tall_ember.jpg);background-position:center 30%"></div></div>'
def evabout(v):
    info=[('Date','Sat 14 Jun 2026'),('Doors','19:00 · Show 20:00'),('Venue','Riverside Arena'),('Age','All ages'),('Duration','3 hours')]
    txt='<div class="m">About</div><div class="l" style="font-size:44px;margin:14px 0 20px;letter-spacing:-.03em">One long summer night on the river.</div><div class="sub" style="max-width:560px">Three stages, eleven acts and food trucks from across the Interior. Gates open at 19:00 and the main set starts at 20:00. Seated and standing tickets are available.</div>'
    il=''.join(f'<div class="row" style="justify-content:space-between;padding:16px 0;border-top:1px solid {"#0d0d0d" if v==3 else "var(--ln)"}"><span class="m">{a}</span><span>{b}</span></div>' for a,b in info)
    mp=f'<div class="art" style="height:260px;border-radius:var(--r);background-image:url({A}w_half.jpg);margin-top:24px;position:relative"><span class="pill k" style="position:absolute;left:20px;bottom:20px">Riverside Arena</span></div>'
    if v==1: return f'<div class="g" style="grid-template-columns:1fr 1fr;gap:80px">{"<div>"+txt+"</div>"}<div>{il}<div style="border-top:1px solid var(--ln)"></div>{mp}</div></div>'
    if v==2: return f'<div class="g" style="grid-template-columns:1.2fr 1fr;gap:24px"><div class="card" style="padding:44px">{txt}</div><div class="card" style="padding:32px">{il}</div></div><div class="art card" style="height:260px;margin-top:24px;background-image:url({A}w_half.jpg)"></div>'
    return f'<div class="l" style="font-size:110px;letter-spacing:-.045em">Sat 14 Jun.<br>Riverside Arena.</div><div class="g" style="grid-template-columns:1fr 1fr;gap:80px;margin-top:48px"><div class="sub" style="font-size:20px;line-height:1.55">Three stages, eleven acts and food trucks from across the Interior. Gates open at 19:00 and the main set starts at 20:00.</div><div>{il}</div></div>'
def evlineup(v):
    acts=[('Nova Reyes','Headliner','a0'),('The Low Tide','Main stage','a1'),('Mira Kole','Main stage','a2'),('Cedar & Pine','Second stage','a4'),('Odd Hours','Second stage','a3'),('Pale Fire','Opening','a5')]
    if v==1: return head(1,'Lineup','Who is playing',tag('6 acts'))+'<div class="g" style="grid-template-columns:repeat(6,1fr);gap:20px">'+''.join(f'<div><div class="art" style="aspect-ratio:1;border-radius:50%;background-image:url({A}{a}.jpg)"></div><div style="font-size:18px;font-weight:500;margin-top:16px">{n}</div><div class="m" style="margin-top:4px">{r}</div></div>' for n,r,a in acts)+'</div><div class="hr" style="margin:56px 0 40px"></div><div class="m">Also this season</div><div class="g" style="grid-template-columns:repeat(3,1fr);gap:28px;margin-top:20px">'+''.join(evcard(1,e) for e in EV[1:4])+'</div>'
    if v==2: return head(2,'Lineup','Who is playing')+'<div class="row" style="gap:16px">'+''.join(f'<div class="card" style="flex:1;padding:20px;text-align:center"><div class="art" style="width:100px;height:100px;border-radius:50%;margin:0 auto;background-image:url({A}{a}.jpg)"></div><div style="font-size:17px;font-weight:600;margin-top:16px">{n}</div><div class="m" style="margin-top:4px">{r}</div></div>' for n,r,a in acts)+'</div><div style="margin-top:56px"></div>'+head(2,'You may also like','Upcoming')+'<div class="g" style="grid-template-columns:repeat(3,1fr);gap:24px">'+''.join(evcard(2,e) for e in EV[1:4])+'</div>'
    return '<div class="m">Lineup</div>'+''.join(f'<div class="row" style="border-top:1.5px solid #0d0d0d;padding:12px 0;align-items:center;justify-content:space-between"><div class="row" style="gap:28px;align-items:center"><span class="m" style="width:32px">0{i+1}</span><div class="l" style="font-size:64px">{n}</div></div><div class="row" style="gap:20px;align-items:center"><span class="m">{r}</span><div class="art" style="width:52px;height:52px;border-radius:50%;background-image:url({A}{a}.jpg)"></div></div></div>' for i,(n,r,a) in enumerate(acts))+'<div style="border-top:1.5px solid #0d0d0d"></div>'
def evtiers(v):
    T=[('General','$45','Standing, all ages','Available'),('Reserved','$84','Numbered seat on the map','Few left'),('VIP','$220','Lounge, early entry, merch','Sold out')]
    def c(i,n,p,d,s):
        dis=s=='Sold out'; mid=i==1
        if v==1: return f'<div style="border-top:1px solid #0d0d0d;padding:20px 28px 0 0"><div class="row" style="justify-content:space-between"><span class="m">{n}</span>{tag(s,"a" if s=="Few left" else "")}</div><div class="l" style="font-size:88px;margin:40px 0 8px">{p}</div><div class="sub" style="font-size:15px">{d}</div><div class="btn {"o" if dis else "a" if mid else ""}" style="margin-top:28px;width:100%">{"Sold out" if dis else "Select"}</div></div>'
        if v==2: return f'<div class="card" style="padding:32px;{"background:#0d0d0d;color:#fff" if mid else ""}"><div class="row" style="justify-content:space-between"><span class="m">{n}</span>{tag(s,"a" if s=="Few left" else "")}</div><div style="font-size:64px;font-weight:300;letter-spacing:-.03em;margin:44px 0 8px">{p}</div><div style="opacity:.6;font-size:15px">{d}</div><div class="btn {"a" if mid else "o" if dis else ""}" style="margin-top:28px;width:100%">{"Sold out" if dis else "Select"}</div></div>'
        return f'<div class="row" style="border-top:1.5px solid #0d0d0d;padding:22px 0;align-items:center;justify-content:space-between"><div><div class="l" style="font-size:56px">{n}</div><div class="m" style="margin-top:8px">{d}</div></div><div class="row" style="gap:24px;align-items:center"><span class="l" style="font-size:56px">{p}</span>{tag(s,"a" if s=="Few left" else "")}<span class="btn {"o" if dis else ""}" style="width:140px">{"Sold out" if dis else "Select"}</span></div></div>'
    body='<div class="g" style="grid-template-columns:repeat(3,1fr);gap:'+('24px' if v!=3 else '0')+'">'+''.join(c(i,*t) for i,t in enumerate(T))+'</div>' if v!=3 else ''.join(c(i,*t) for i,t in enumerate(T))+'<div style="border-top:1.5px solid #0d0d0d"></div>'
    bar=f'<div class="card row" style="margin-top:40px;padding:16px 16px 16px 32px;align-items:center;justify-content:space-between;{"border-radius:999px;" if v!=1 else ""}"><div><div class="m">Summer Stage · Sat 14 Jun</div><div style="font-size:18px;margin-top:4px">From <b>$45</b> · 482 tickets left</div></div><span class="btn a" style="padding:0 48px">Continue to booking</span></div>'
    return head(v,'Choose tickets','Tickets')+body+bar
